replacements={'ATLAS_DATA':encoded,'ATLAS_W':str(w),'ATLAS_H':str(h),'HERO_HAMSTER':sprite('hamster','hero-hamster'),'LEVEL_LIST':level_list,'TRAY':tray,'MINI_HAMSTER':sprite('hamster'),'MINI_PADDLE':sprite('paddle'),'SPECIAL_ART':sprite('gift','special-art'),'RECIPES':recipes,'INGREDIENTS':ingredients,'POWERUPS':powerups,'MARKET_ART':sprite('jam'),'SOUND_ART':sprite('cracker')}
